import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  h1ClassName,
  h2ClassName,
  h3ClassName,
  inlineCodeClassName,
  listClassName,
  mutedClassName,
  paragraphClassName,
} from "./view";

export {
  h1ClassName,
  h2ClassName,
  h3ClassName,
  inlineCodeClassName,
  listClassName,
  mutedClassName,
  paragraphClassName,
} from "./view";

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const h1 = <ParentMessage>(label: string, className?: string): Html => {
  const h = html<ParentMessage>();
  return h.h1([h.Class(classNames(h1ClassName, className))], [label]);
};

export const h2 = <ParentMessage>(label: string, className?: string): Html => {
  const h = html<ParentMessage>();
  return h.h2([h.Class(classNames(h2ClassName, className))], [label]);
};

export const h3 = <ParentMessage>(label: string, className?: string): Html => {
  const h = html<ParentMessage>();
  return h.h3([h.Class(classNames(h3ClassName, className))], [label]);
};

export const p = <ParentMessage>(label: string, className?: string): Html => {
  const h = html<ParentMessage>();
  return h.p([h.Class(classNames(paragraphClassName, className))], [label]);
};

export const muted = <ParentMessage>(
  label: string,
  className?: string
): Html => {
  const h = html<ParentMessage>();
  return h.p([h.Class(classNames(mutedClassName, className))], [label]);
};

export const inlineCode = <ParentMessage>(
  label: string,
  className?: string
): Html => {
  const h = html<ParentMessage>();
  return h.code([h.Class(classNames(inlineCodeClassName, className))], [label]);
};

export const ul = <ParentMessage>(
  items: readonly string[],
  className?: string
): Html => {
  const h = html<ParentMessage>();
  return h.ul(
    [h.Class(classNames(listClassName, className))],
    items.map((item) => h.li([], [item]))
  );
};

export const h1ClassName =
  "scroll-m-20 text-4xl font-extrabold tracking-normal text-gray-950";

export const h2ClassName =
  "scroll-m-20 border-b border-gray-200 pb-2 text-3xl font-semibold tracking-normal text-gray-950";

export const h3ClassName =
  "scroll-m-20 text-2xl font-semibold tracking-normal text-gray-950";

export const paragraphClassName = "leading-7 text-gray-700";

export const mutedClassName = "text-sm text-gray-500";

export const inlineCodeClassName =
  "relative rounded bg-gray-100 px-1.5 py-0.5 font-mono text-sm font-semibold text-gray-900";

export const listClassName = "my-6 ml-6 list-disc [&>li]:mt-2";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Typography from "./index";

const view = (): Html => {
  const h = html<never>();

  return h.div(
    [],
    [
      Typography.h1("Component registry"),
      Typography.h2("Principles"),
      Typography.p("Reusable text helpers."),
      Typography.inlineCode("className"),
    ]
  );
};

describe("Typography registry view", () => {
  test("renders the documented static surface", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("Component registry")).toExist(),
      Scene.expect(Scene.text("Principles")).toExist()
    );
  });
});
